// crc64: CRC-64/XZ of 8 MiB of generated bytes, table-driven. Prints the
// CRC in hexadecimal.
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    uint64_t table[256];
    for (int b = 0; b < 256; b++) {
        uint64_t c = (uint64_t)b;
        for (int k = 0; k < 8; k++) c = c & 1 ? c >> 1 ^ 0xC96C5795D7870F42ull : c >> 1;
        table[b] = c;
    }
    int64_t n = 1 << 23;
    uint8_t *data = malloc(n);
    for (int64_t i = 0; i < n; i++) data[i] = (uint8_t)((i * 2654435761) >> 13 & 255);
    uint64_t c = ~0ull;
    for (int64_t i = 0; i < n; i++) c = table[(c ^ data[i]) & 255] ^ c >> 8;
    printf("%016llx\n", (unsigned long long)~c);
    return 0;
}
